// ── Error mapping ──

internal fun FfiException.toDomain(): DspiException =
    when (this) {
        is FfiException.Disconnected -> DspiException.Disconnected()
        is FfiException.Transfer -> DspiException.Transfer(msg)
        is FfiException.Refused -> DspiException.Refused(status.toInt())
        is FfiException.InvalidArgument -> DspiException.InvalidArgument(msg)
        is FfiException.Unsupported -> DspiException.Unsupported()
        is FfiException.ReadOnly -> DspiException.ReadOnly()
        is FfiException.Locked -> DspiException.Locked()
        is FfiException.Denied -> DspiException.Denied()
        is FfiException.Link -> DspiException.Link(code, msg)
        is FfiException.Io -> DspiException.Io(msg)
        is FfiException.AutoEq -> DspiException.AutoEq(code, msg, retryAfterS?.let { it.toLong() })
        is FfiException.FirmwareGuardBlocked -> DspiException.FirmwareGuardBlocked(msg)
        is FfiException.OvervoltWordRequired -> DspiException.OvervoltWordRequired(msg)
        is FfiException.ConfirmationRequired -> DspiException.ConfirmationRequired(code, msg)
        is FfiException.LimitExceeded -> DspiException.LimitExceeded(code, msg)
        is FfiException.InstallerLock -> DspiException.InstallerLock(code, msg)
        is FfiException.ImageRefused -> DspiException.ImageRefused(msg)
        is FfiException.LimitsUnknown -> DspiException.LimitsUnknown(msg)
    }

internal fun DspiException.toFfi(): FfiException =
    when (this) {
        is DspiException.Disconnected -> FfiException.Disconnected()
        is DspiException.Transfer -> FfiException.Transfer(msg)
        is DspiException.Refused -> FfiException.Refused(status.toUByte())
        is DspiException.InvalidArgument -> FfiException.InvalidArgument(msg)
        is DspiException.Unsupported -> FfiException.Unsupported()
        is DspiException.ReadOnly -> FfiException.ReadOnly()
        is DspiException.Locked -> FfiException.Locked()
        is DspiException.Denied -> FfiException.Denied()
        is DspiException.Link -> FfiException.Link(code, msg)
        is DspiException.Io -> FfiException.Io(msg)
        is DspiException.AutoEq -> FfiException.AutoEq(code, msg, retryAfterS?.let { it.toUInt() })
        is DspiException.FirmwareGuardBlocked -> FfiException.FirmwareGuardBlocked(msg)
        is DspiException.OvervoltWordRequired -> FfiException.OvervoltWordRequired(msg)
        is DspiException.ConfirmationRequired -> FfiException.ConfirmationRequired(code, msg)
        is DspiException.LimitExceeded -> FfiException.LimitExceeded(code, msg)
        is DspiException.InstallerLock -> FfiException.InstallerLock(code, msg)
        is DspiException.ImageRefused -> FfiException.ImageRefused(msg)
        is DspiException.LimitsUnknown -> FfiException.LimitsUnknown(msg)
    }

